const n='\x3c!--\n  SPA Loading Template\n  \n  Shown instantly while the Vue app JS bundle is downloading, parsing, and hydrating.\n  This is pure HTML/CSS — zero JavaScript — so it paints on first byte.\n  Nuxt automatically injects this into the HTML shell and removes it once the app mounts.\n  \n  Critical for Lighthouse FCP score in SPA (ssr: false) mode.\n  For SSR pages (auth), this template is not used — the server-rendered HTML\n  provides the FCP/LCP content directly.\n--\x3e\n<div id="spa-loader">\n  <img src="/logos/logo-full.svg" alt="FlyLive" width="140" height="88" class="spa-loader__logo" fetchpriority="high" />\n  <div class="spa-loader__spinner"></div>\n</div>\n\n<style>\n  #spa-loader {\n    position: fixed;\n    inset: 0;\n    z-index: 999999;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    gap: 24px;\n    background: #000002;\n  }\n\n  .spa-loader__logo {\n    width: 140px;\n    height: 88px;\n    border-radius: 20px;\n    animation: spa-logo-pulse 1.8s ease-in-out infinite;\n  }\n\n  .spa-loader__spinner {\n    width: 32px;\n    height: 32px;\n    border: 3px solid rgba(255, 36, 101, 0.2);\n    border-top-color: #ff2465;\n    border-radius: 50%;\n    animation: spa-spin 0.8s linear infinite;\n  }\n\n  @keyframes spa-spin {\n    to {\n      transform: rotate(360deg);\n    }\n  }\n\n  @keyframes spa-logo-pulse {\n\n    0%,\n    100% {\n      opacity: 1;\n      transform: scale(1);\n    }\n\n    50% {\n      opacity: 0.7;\n      transform: scale(0.95);\n    }\n  }\n\n  /* Respect reduced motion */\n  @media (prefers-reduced-motion: reduce) {\n    .spa-loader__logo {\n      animation: none;\n    }\n\n    .spa-loader__spinner {\n      animation: none;\n      border-color: #ff2465;\n    }\n  }\n</style>';export{n as template};
